/**
 * Navigation between product categories as chips, a bar with an underline, a side list, tiles with a big icon,
 * or chips under a toolbar (search, sort and the number shown). The current one carries aria-current. Axes:
 * layout (chips, bar, sidebar, tiles, toolbar), count (show, hide), icon (show, hide), density.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Container } from "../primitives/container/container";
import { Group } from "../primitives/group/group";
import { Inline } from "../primitives/inline/inline";
import { Link } from "../primitives/link/link";
import { List } from "../primitives/list/list";
import { ListItem } from "../primitives/list/list-item";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Select } from "../primitives/select/select";
import { SelectOption } from "../primitives/select/select-option";
import { Text } from "../primitives/text/text";
import { SearchField } from "../components/search-field";
import { cn } from "../utils";
import type { Category, CategoryTools } from "./category-nav.types";

export type CategoryNavProps = {
  label: string;
  categories: Category[];
  current?: string;
  layout?: "chips" | "bar" | "sidebar" | "tiles" | "toolbar";
  count?: "show" | "hide";
  icon?: "show" | "hide";
  density?: "default" | "compact";
  tools?: CategoryTools;
  landmarkLabel?: string;
};

export function CategoryNav({
  label,
  categories,
  current = "all",
  layout = "chips",
  count = "show",
  icon = "show",
  density = "default",
  tools,
  landmarkLabel,
}: CategoryNavProps) {
  const chipLike = ((layout as string) === "chips") || ((layout as string) === "toolbar");
  const tiles = (layout as string) === "tiles";
  const linkShape =
    chipLike ? "inline-flex items-center gap-2 rounded px-3 py-1.5 inset-ring inset-ring-border"
    : (layout as string) === "bar" ? "inline-flex items-center gap-2 -mb-px border-b px-1 py-2"
    : tiles ? "flex h-full flex-col items-start gap-4 rounded p-4 inset-ring inset-ring-border"
    : "inline-flex w-full items-center gap-2 rounded px-3 py-2";
  const currentLook =
    chipLike ? "bg-primary text-primary-foreground"
    : (layout as string) === "bar" ? "border-foreground font-semibold"
    : tiles ? "inset-ring-foreground font-semibold"
    : "bg-muted font-semibold";
  const otherLook = ((layout as string) === "bar") ? "border-transparent" : "";
  const listShape =
    (layout as string) === "sidebar" ? "flex flex-col gap-2"
    : (layout as string) === "bar" ? "flex flex-wrap gap-2 gap-x-4 border-b border-border"
    : tiles ? "grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-6"
    : "flex flex-wrap gap-2";
  return (
    <Block tag="nav" aria-label={(landmarkLabel ?? label)} data-testid="category-nav" data-layout={layout}>
      <Container
        className={cn(
          "mx-auto w-full max-w-6xl px-4",
          (((density as string) === "compact") ? "py-2" : "py-4")
        )}
        data-slot="container"
      >
        {((layout as string) === "toolbar") ? (
          <Group gap="4" align="center" className="mb-4 flex-wrap" data-testid="toolbar">
            <SearchField value={(tools?.query ?? "")} label={(tools?.search ?? "")} placeholder={tools?.search} />
            <Select name="sort" size="sm" aria-label={tools?.sort} className="w-48">
              <SelectOption value="sort" label={tools?.sortValue} selected={true} />
            </Select>
            <Text size="sm" className="text-muted-foreground">
              {tools?.shown}
            </Text>
          </Group>
        ) : null}
        <List tag="ul" className={listShape} data-testid="items">
          {(categories ?? []).map((c) => (
            <ListItem key={c.id}>
              <Link
                href="#/categories"
                variant="default"
                aria-current={((c.id === current) ? "page" : undefined)}
                className={cn("text-sm", linkShape, ((c.id === current) ? currentLook : otherLook))}
                data-testid="item"
              >
                {((icon as string) === "show") ? (
                  <>
                    {tiles ? (
                      <Inline className="flex size-10 items-center justify-center rounded bg-muted">
                        <LucideIcon name={c.icon} size={20} />
                      </Inline>
                    ) : (
                      <LucideIcon name={c.icon} size={16} />
                    )}
                  </>
                ) : null}
                <Inline>
                  {c.name}
                </Inline>
                {((count as string) === "show") ? (
                  <Text size="xs" className="text-muted-foreground">
                    {(c.count == null ? undefined : String(c.count))}
                  </Text>
                ) : null}
              </Link>
            </ListItem>
          ))}
        </List>
      </Container>
    </Block>
  );
}

