export type Category = {
  id: string;
  name: string;
  icon: string;
  count: number;
};

export type CategoryTools = {
  /** label of the search field */
  search?: string;
  /** label of the sort select */
  sort?: string;
  /** the chosen sort */
  sortValue?: string;
  /** how many products are shown */
  shown?: string;
  /** the text in the search field */
  query?: string;
};
